use std::fs::File;
use std::io::{self, Read, Write};
use std::path::PathBuf;
use clap::Parser;
use blake3::{Hasher, OutputReader};

#[derive(Parser, Debug)]
#[command(name = "b3sum", version = "1.8.4", about = "BLAKE3 hashing tool")]
struct Args {
    #[arg(name = "FILE")]
    files: Vec<String>,

    #[arg(long)]
    keyed: bool,

    #[arg(long, value_name = "CONTEXT")]
    derive_key: Option<String>,

    #[arg(short = 'l', long, default_value_t = 32)]
    length: u64,

    #[arg(long, default_value_t = 0)]
    seek: u64,

    #[arg(long)]
    num_threads: Option<usize>,

    #[arg(long)]
    no_mmap: bool,

    #[arg(long)]
    no_names: bool,

    #[arg(long)]
    raw: bool,

    #[arg(long)]
    tag: bool,

    #[arg(short = 'c', long)]
    check: bool,

    #[arg(long)]
    quiet: bool,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    if let Some(num_threads) = args.num_threads {
        if num_threads > 0 {
            rayon::ThreadPoolBuilder::new()
                .num_threads(num_threads)
                .build_global()?;
        }
    }

    if args.check {
        todo!("Implement check mode");
    }

    let mut key = [0u8; 32];
    if args.keyed {
        io::stdin().read_exact(&mut key)?;
    }

    if args.files.is_empty() {
        hash_file("-", &args, &key)?;
    } else {
        if args.raw && args.files.len() > 1 {
            anyhow::bail!("--raw allows only one input");
        }
        for file in &args.files {
            hash_file(file, &args, &key)?;
        }
    }

    Ok(())
}

fn hash_file(path: &str, args: &Args, key: &[u8; 32]) -> anyhow::Result<()> {
    let mut hasher = if args.keyed {
        Hasher::new_keyed(key)
    } else if let Some(context) = &args.derive_key {
        Hasher::new_derive_key(context)
    } else {
        Hasher::new()
    };

    if path == "-" {
        io::copy(&mut io::stdin(), &mut hasher)?;
    } else {
        let mut file = File::open(path)?;
        io::copy(&mut file, &mut hasher)?;
    }

    let mut output_reader = hasher.finalize_xof();
    output_reader.set_position(args.seek);

    let mut output = vec![0u8; args.length as usize];
    output_reader.fill(&mut output);

    if args.raw {
        io::stdout().write_all(&output)?;
    } else {
        let hex_output = hex::encode(output);
        if args.tag {
            println!("BLAKE3 ({}) = {}", path, hex_output);
        } else if args.no_names {
            println!("{}", hex_output);
        } else {
            println!("{}  {}", hex_output, path);
        }
    }

    Ok(())
}
EOF
