    num_threads: Option<usize>,

    #[arg(long)]
    no_mmap: bool,

    #[arg(long)]
    no_names: bool,

    #[arg(long)]
    raw: bool,

    #[arg(long)]
    tag: bool,

    #[arg(short = 'c', long)]
    check: bool,

    #[arg(long)]
    quiet: bool,
}

fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    if let Some(num_threads) = args.num_threads {
        if num_threads > 0 {
            rayon::ThreadPoolBuilder::new()
                .num_threads(num_threads)
                .build_global()
                .ok(); // Ignore error if already initialized
        }
    }

    let mut key = [0u8; 32];
    if args.keyed {
        io::stdin().read_exact(&mut key)?;
    }

    if args.check {
        return run_check(&args, &key);
    }

    if args.files.is_empty() {
        hash_file("-", &args, &key)?;
    } else {
        if args.raw && args.files.len() > 1 {
            anyhow::bail!("--raw allows only one input");
        }
        for file in &args.files {
            if let Err(e) = hash_file(file, &args, &key) {
                eprintln!("b3sum: {}: {}", file, e);
            }
        }
    }

    Ok(())
}

fn hash_file(path: &str, args: &Args, key: &[u8; 32]) -> anyhow::Result<()> {
    let mut hasher = if args.keyed {
        Hasher::new_keyed(key)
    } else if let Some(context) = &args.derive_key {
        Hasher::new_derive_key(context)
    } else {
        Hasher::new()
    };

    if path == "-" {
        io::copy(&mut io::stdin().lock(), &mut hasher)?;
    } else {
        let file = File::open(path)?;
        let metadata = file.metadata()?;
        if !args.no_mmap && metadata.is_file() && metadata.len() > 0 {
            let mmap = unsafe { MmapOptions::new().map(&file)? };
            hasher.update_rayon(&mmap);
        } else {
            io::copy(&mut BufReader::new(file), &mut hasher)?;
        }
    }

    let mut output_reader = hasher.finalize_xof();
    output_reader.set_position(args.seek);

    let mut output = vec![0u8; args.length as usize];
    output_reader.fill(&mut output);

    if args.raw {
        io::stdout().write_all(&output)?;
    } else {
        let hex_output = hex::encode(output);
        if args.tag {
            println!("BLAKE3 ({}) = {}", path, hex_output);
        } else if args.no_names {
            println!("{}", hex_output);
        } else {
            println!("{}  {}", hex_output, path);
        }
    }

    Ok(())
}

fn run_check(args: &Args, key: &[u8; 32]) -> anyhow::Result<()> {
    for checkfile in &args.files {
        let file = if checkfile == "-" {
            Box::new(io::stdin().lock()) as Box<dyn BufRead>
        } else {
            Box::new(BufReader::new(File::open(checkfile)?)) as Box<dyn BufRead>
        };

        for line in file.lines() {
            let line = line?;
            let (hash_str, path) = if line.starts_with("BLAKE3 (") {
                // BSD style: BLAKE3 (path) = hash
                let parts: Vec<&str> = line.split(" = ").collect();
                if parts.len() != 2 { continue; }
                let hash = parts[1];
                let path_part = parts[0].trim_start_matches("BLAKE3 (");
                let path = &path_part[..path_part.len()-1];
                (hash, path)
            } else {
                // Normal style: hash  path
                let parts: Vec<&str> = line.splitn(2, "  ").collect();
                if parts.len() != 2 { continue; }
                (parts[0], parts[1])
            };

            let mut hasher = if args.keyed {
                Hasher::new_keyed(key)
            } else if let Some(context) = &args.derive_key {
                Hasher::new_derive_key(context)
            } else {
                Hasher::new()
            };

            let success = match File::open(path) {
                Ok(mut f) => {
                    io::copy(&mut f, &mut hasher)?;
                    let mut output = vec![0u8; args.length as usize];
                    hasher.finalize_xof().fill(&mut output);
                    hex::encode(output) == hash_str
                }
                Err(_) => false,
            };

            if success {
                if !args.quiet {
                    println!("{}: OK", path);
                }
            } else {
                println!("{}: FAILED", path);
            }
        }
    }
    Ok(())
}
