#[command(name = "b3sum", version = "1.8.4", about = "BLAKE3 hashing tool", disable_help_flag = true)]
struct Args {
    #[arg(name = "FILE")]
    files: Vec<String>,

    #[arg(long)]
    keyed: bool,

    #[arg(long, value_name = "CONTEXT")]
    derive_key: Option<String>,

    #[arg(short = 'l', long, default_value_t = 32)]
    length: u64,

    #[arg(long, default_value_t = 0)]
    seek: u64,

    #[arg(long)]
    num_threads: Option<usize>,

    #[arg(long)]
    no_mmap: bool,

    #[arg(long)]
    no_names: bool,

    #[arg(long)]
    raw: bool,

    #[arg(long)]
    tag: bool,

    #[arg(short = 'c', long)]
    check: bool,

    #[arg(long)]
    quiet: bool,

    #[arg(short = 'h', long, action = clap::ArgAction::Help)]
    help: Option<bool>,

    #[arg(short = 'V', long, action = clap::ArgAction::Version)]
    version: Option<bool>,
}

fn main() {
    let args = Args::parse();

    if args.quiet && !args.check {
        eprintln!("error: the following required arguments were not provided:\n  --check\n\nUsage: b3sum --check --quiet <FILE>...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    if args.check {
        if args.keyed {
            eprintln!("error: the argument '--keyed' cannot be used with '--check'\n\nUsage: b3sum --keyed <FILE>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if args.derive_key.is_some() {
            eprintln!("error: the argument '--derive-key <CONTEXT>' cannot be used with '--check'\n\nUsage: b3sum --derive-key <CONTEXT> <FILE>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if args.length != 32 {
            eprintln!("error: the argument '--length <LEN>' cannot be used with '--check'\n\nUsage: b3sum --length <LEN> <FILE>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if args.seek != 0 {
             eprintln!("error: the argument '--seek <SEEK>' cannot be used with '--check'\n\nUsage: b3sum --seek <SEEK> <FILE>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if args.raw {
             eprintln!("error: the argument '--raw' cannot be used with '--check'\n\nUsage: b3sum --raw <FILE>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        if args.no_names {
             eprintln!("error: the argument '--no-names' cannot be used with '--check'\n\nUsage: b3sum --no-names <FILE>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
    }

    if args.keyed && args.derive_key.is_some() {
        eprintln!("error: the argument '--keyed' cannot be used with '--derive-key <CONTEXT>'\n\nUsage: b3sum --keyed <FILE>...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    if let Some(num_threads) = args.num_threads {
        if num_threads > 0 {
            rayon::ThreadPoolBuilder::new()
                .num_threads(num_threads)
                .build_global()
                .ok();
        }
    }

    let mut key = [0u8; 32];
    if args.keyed {
        let mut stdin = io::stdin().lock();
        let mut buffer = [0u8; 33];
        let n = stdin.read(&mut buffer).unwrap_or(0);
        if n < 32 {
            eprintln!("Error: expected 32 key bytes from stdin, found {}", n);
            std::process::exit(1);
        }
        if n > 32 {
            eprintln!("Error: read more than 32 key bytes from stdin");
            std::process::exit(1);
        }
        key.copy_from_slice(&buffer[..32]);
    }

    if args.check {
        match run_check(&args, &key) {
            Ok(true) => std::process::exit(0),
            Ok(false) => std::process::exit(1),
            Err(e) => {
                eprintln!("b3sum: {}", e);
                std::process::exit(1);
            }
        }
    }

    let mut exit_code = 0;
    if args.files.is_empty() {
        if let Err(e) = hash_file("-", &args, &key) {
            eprintln!("b3sum: -: {}", e);
            exit_code = 1;
        }
    } else {
        if args.raw && args.files.len() > 1 {
            eprintln!("Error: Only one filename can be provided when using --raw");
            std::process::exit(1);
        }
        for file in &args.files {
            if let Err(e) = hash_file(file, &args, &key) {
                eprintln!("b3sum: {}: {}", file, e);
                exit_code = 1;
            }
        }
    }
    std::process::exit(exit_code);
}

fn hash_file(path: &str, args: &Args, key: &[u8; 32]) -> io::Result<()> {
    let mut hasher = if args.keyed {
        Hasher::new_keyed(key)
    } else if let Some(context) = &args.derive_key {
        Hasher::new_derive_key(context)
    } else {
        Hasher::new()
    };

    if path == "-" {
        io::copy(&mut io::stdin().lock(), &mut hasher)?;
    } else {
        let file = File::open(path)?;
        let metadata = file.metadata()?;
        if !args.no_mmap && metadata.is_file() && metadata.len() > 0 {
            let mmap = unsafe { MmapOptions::new().map(&file)? };
            hasher.update_rayon(&mmap);
        } else {
            let mut reader = BufReader::new(file);
            io::copy(&mut reader, &mut hasher)?;
        }
    }

    let mut output_reader = hasher.finalize_xof();
    output_reader.set_position(args.seek);

    let mut output = vec![0u8; args.length as usize];
    output_reader.fill(&mut output);

    if args.raw {
        io::stdout().write_all(&output)?;
    } else {
        let hex_output = hex::encode(output);
        if args.tag {
            println!("BLAKE3 ({}) = {}", path, hex_output);
        } else if args.no_names {
            println!("{}", hex_output);
        } else {
            println!("{}  {}", hex_output, path);
        }
    }

    Ok(())
}

fn run_check(args: &Args, key: &[u8; 32]) -> io::Result<bool> {
    let mut total_failed = 0;
    let mut any_error = false;

    let files_to_check = if args.files.is_empty() {
        vec!["-".to_string()]
    } else {
        args.files.clone()
    };

    for checkfile in files_to_check {
        let reader: Box<dyn BufRead> = if checkfile == "-" {
            Box::new(BufReader::new(io::stdin().lock()))
        } else {
            match File::open(&checkfile) {
                Ok(f) => Box::new(BufReader::new(f)),
                Err(e) => {
                    eprintln!("b3sum: {}: {}", checkfile, e);
                    any_error = true;
                    continue;
                }
            }
        };

        for line in reader.lines() {
            let line = match line {
                Ok(l) => l,
                Err(e) => {
                    eprintln!("b3sum: {}: error reading line: {}", checkfile, e);
                    any_error = true;
                    continue;
                }
            };

            let (hash_str, path) = if line.starts_with("BLAKE3 (") {
                if let Some(eq_idx) = line.rfind(" = ") {
                    let path_part = &line[8..eq_idx];
                    if path_part.ends_with(')') {
                        let path = &path_part[..path_part.len() - 1];
                        let hash = &line[eq_idx + 3..];
                        (hash, path)
                    } else {
                        eprintln!("b3sum: Invalid check line format");
                        total_failed += 1;
                        any_error = true;
                        continue;
                    }
                } else {
                    eprintln!("b3sum: Invalid check line format");
                    total_failed += 1;
                    any_error = true;
                    continue;
                }
            } else {
                let parts: Vec<&str> = line.splitn(2, "  ").collect();
                if parts.len() != 2 {
                    eprintln!("b3sum: Invalid check line format");
                    total_failed += 1;
                    any_error = true;
                    continue;
                }
                (parts[0], parts[1])
            };

            if hash_str.len() != 64 || !hash_str.chars().all(|c| c.is_ascii_hexdigit()) {
                eprintln!("b3sum: Invalid hash length");
                total_failed += 1;
                any_error = true;
                continue;
            }

            let mut hasher = if args.keyed {
                Hasher::new_keyed(key)
            } else if let Some(context) = &args.derive_key {
                Hasher::new_derive_key(context)
            } else {
                Hasher::new()
            };

            let check_result = match File::open(path) {
                Ok(file) => {
                    let metadata = file.metadata()?;
                    if !args.no_mmap && metadata.is_file() && metadata.len() > 0 {
                        let mmap = unsafe { MmapOptions::new().map(&file)? };
                        hasher.update_rayon(&mmap);
                    } else {
                        io::copy(&mut BufReader::new(file), &mut hasher)?;
                    }
                    let hash = hasher.finalize();
                    if hash.to_hex().as_str() == hash_str {
                        Ok(())
                    } else {
                        Err(io::Error::new(io::ErrorKind::Other, "checksum mismatch"))
                    }
                }
                Err(e) => Err(e),
            };

            match check_result {
                Ok(_) => {
                    if !args.quiet {
                        println!("{}: OK", path);
                    }
                }
                Err(e) => {
                    if e.kind() == io::ErrorKind::Other && e.to_string() == "checksum mismatch" {
                        println!("{}: FAILED", path);
                    } else {
                        println!("{}: FAILED ({})", path, e);
                    }
                    total_failed += 1;
                    any_error = true;
                }
            }
        }
    }

    if total_failed > 0 {
        eprintln!("b3sum: WARNING: {} computed checksum{} did NOT match", total_failed, if total_failed > 1 { "s" } else { "" });
    }

    Ok(!any_error && total_failed == 0)
}
EOF
