struct Hasher {
    key: [u32; 8],
    flags: u32,
    stack: Vec<[u32; 8]>,
    chunk_buf: [u8; 1024],
    chunk_buf_len: usize,
    chunk_counter: u64,
}

impl Hasher {
    fn new_internal(key: [u32; 8], flags: u32) -> Self {
        Self { key, flags, stack: Vec::new(), chunk_buf: [0u8; 1024], chunk_buf_len: 0, chunk_counter: 0 }
    }
    fn new() -> Self { Self::new_internal(IV, 0) }
    fn new_keyed(key: &[u8; 32]) -> Self {
        let mut k = [0u32; 8];
        for i in 0..8 { k[i] = u32::from_le_bytes(key[i * 4..i * 4 + 4].try_into().unwrap()); }
        Self::new_internal(k, KEYED_HASH)
    }
    fn new_derive_key(context: &str) -> Self {
        let mut h = Self::new_internal(IV, DERIVE_KEY_CONTEXT);
        h.update(context.as_bytes());
        let mut key = [0u8; 32];
        h.finalize_xof(0, &mut key);
        let mut k = [0u32; 8];
        for i in 0..8 { k[i] = u32::from_le_bytes(key[i * 4..i * 4 + 4].try_into().unwrap()); }
        Self::new_internal(k, DERIVE_KEY_MATERIAL)
    }

    fn update(&mut self, mut data: &[u8]) {
        while !data.is_empty() {
            if self.chunk_buf_len == 1024 {
                let cv = self.finalize_chunk();
                self.push_stack(cv);
                self.chunk_buf_len = 0;
                self.chunk_counter += 1;
            }
            let take = std::cmp::min(data.len(), 1024 - self.chunk_buf_len);
            self.chunk_buf[self.chunk_buf_len..self.chunk_buf_len + take].copy_from_slice(&data[..take]);
            self.chunk_buf_len += take;
            data = &data[take..];
        }
    }

    fn finalize_chunk(&self) -> [u32; 8] {
        let mut cv = self.key;
        let mut blocks = (self.chunk_buf_len + 63) / 64;
        if blocks == 0 { blocks = 1; }
        for i in 0..blocks {
            let mut flags = self.flags;
            if i == 0 { flags |= CHUNK_START; }
            if i == blocks - 1 { flags |= CHUNK_END; }
            let start = i * 64;
            let end = std::cmp::min(start + 64, self.chunk_buf_len);
            let mut block = [0u8; 64];
            block[..end - start].copy_from_slice(&self.chunk_buf[start..end]);
            let out = compress(&cv, &block, self.chunk_counter, (end - start) as u32, flags);
            cv.copy_from_slice(&out[0..8]);
        }
        cv
    }

    fn push_stack(&mut self, mut cv: [u32; 8]) {
        let mut i = 0;
        while (self.chunk_counter >> i) & 1 != 0 {
            let left = self.stack.pop().unwrap();
            cv = self.parent_cv(&left, &cv, self.flags);
            i += 1;
        }
        self.stack.push(cv);
    }

    fn parent_cv(&self, left: &[u32; 8], right: &[u32; 8], flags: u32) -> [u32; 8] {
        let mut block = [0u8; 64];
        for i in 0..8 {
            block[i * 4..i * 4 + 4].copy_from_slice(&left[i].to_le_bytes());
