        self.stack.push(cv);
    }

    fn parent_cv(&self, left: &[u32; 8], right: &[u32; 8], flags: u32) -> [u32; 8] {
        let mut block = [0u8; 64];
        for i in 0..8 {
            block[i * 4..i * 4 + 4].copy_from_slice(&left[i].to_le_bytes());
            block[32 + i * 4..32 + i * 4 + 4].copy_from_slice(&right[i].to_le_bytes());
        }
        let out = compress(&self.key, &block, 0, 64, flags | PARENT);
        let mut res = [0u32; 8];
        res.copy_from_slice(&out[0..8]);
        res
    }

    fn finalize_xof(&self, seek: u64, out: &mut [u8]) {
        if self.stack.is_empty() {
            self.output_at_root(seek, out);
        } else {
            let mut current_cv = self.finalize_chunk();
            let mut stack = self.stack.clone();
            while let Some(left) = stack.pop() {
                if stack.is_empty() {
                    self.parent_at_root(&left, &current_cv, seek, out);
                    return;
                } else {
                    current_cv = self.parent_cv(&left, &current_cv, self.flags);
                }
            }
        }
    }

    fn output_at_root(&self, seek: u64, out: &mut [u8]) {
        let mut cv = self.key;
        let blocks = (self.chunk_buf_len + 63) / 64;
        let n = if blocks == 0 { 1 } else { blocks };
        for i in 0..n-1 {
            let f = if i == 0 { self.flags | CHUNK_START } else { self.flags };
            let mut block = [0u8; 64];
            block.copy_from_slice(&self.chunk_buf[i*64..i*64+64]);
            let res = compress(&cv, &block, self.chunk_counter, 64, f);
            cv.copy_from_slice(&res[0..8]);
        }
        let i = n - 1;
        let mut f = self.flags | CHUNK_END | ROOT;
        if i == 0 { f |= CHUNK_START; }
        let start = i * 64;
        let end = std::cmp::min(start + 64, self.chunk_buf_len);
        let mut block = [0u8; 64];
        block[..end - start].copy_from_slice(&self.chunk_buf[start..end]);
        self.output_full(&cv, &block, self.chunk_counter, (end - start) as u32, f, seek, out);
    }

    fn parent_at_root(&self, left: &[u32; 8], right: &[u32; 8], seek: u64, out: &mut [u8]) {
        let mut block = [0u8; 64];
        for i in 0..8 {
            block[i * 4..i * 4 + 4].copy_from_slice(&left[i].to_le_bytes());
            block[32 + i * 4..32 + i * 4 + 4].copy_from_slice(&right[i].to_le_bytes());
        }
        self.output_full(&self.key, &block, 0, 64, self.flags | PARENT | ROOT, seek, out);
    }

    fn output_full(&self, cv_in: &[u32; 8], block: &[u8; 64], _t: u64, len: u32, flags: u32, seek: u64, out: &mut [u8]) {
        let mut block_idx = seek / 64;
        let mut skip = (seek % 64) as usize;
        let mut i = 0;
        while i < out.len() {
            let res = compress(cv_in, block, block_idx, len, flags);
            for word in &res {
                for byte in word.to_le_bytes() {
                    if skip > 0 { skip -= 1; }
                    else if i < out.len() {
                        out[i] = byte;
                        i += 1;
                    }
                }
            }
            block_idx += 1;
        }
    }
}

fn hex_encode(data: &[u8]) -> String {
    data.iter().map(|b| format!("{:02x}", b)).collect()
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.iter().any(|a| a == "-V" || a == "--version") {
        println!("b3sum 1.8.4");
        return;
    }
    if args.iter().any(|a| a == "-h" || a == "--help") {
        print_help();
        return;
    }

    let mut files = Vec::new();
    let mut keyed = false;
    let mut derive_key = None;
    let mut length = 32;
    let mut seek = 0;
    let mut no_names = false;
    let mut raw = false;
    let mut tag = false;
    let mut check = false;
    let mut quiet = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--keyed" => keyed = true,
            "--derive-key" => { i += 1; if i < args.len() { derive_key = Some(args[i].clone()); } }
            "-l" | "--length" => { i += 1; if i < args.len() { length = args[i].parse().unwrap_or(32); } }
            "--seek" => { i += 1; if i < args.len() { seek = args[i].parse().unwrap_or(0); } }
            "--no-names" => no_names = true,
            "--raw" => raw = true,
            "--tag" => tag = true,
            "-c" | "--check" => check = true,
            "--quiet" => quiet = true,
            "--no-mmap" | "--num-threads" => { if !args[i].starts_with("--no") { i += 1; } }
            f if f.starts_with('-') && f.len() > 1 => {
                for c in f[1..].chars() {
                    match c {
                        'c' => check = true,
                        _ => {}
                    }
                }
            }
            _ => files.push(args[i].clone()),
        }
        i += 1;
    }

    if quiet && !check {
        eprintln!("error: the following required arguments were not provided:\n  --check\n\nUsage: executable --check --quiet <FILE>...\n\nFor more information, try '--help'.");
        std::process::exit(2);
    }

    if check {
        run_check(&files, quiet);
        return;
    }

    let mut key = [0u8; 32];
    if keyed {
        if files.is_empty() {
            eprintln!("error: the following required arguments were not provided:\n  <FILE>...\n\nUsage: executable --keyed <FILE>...\n\nFor more information, try '--help'.");
            std::process::exit(2);
        }
        let mut key_data = Vec::new();
        let mut buf = [0u8; 1];
        let mut stdin = io::stdin().lock();
        while let Ok(n) = stdin.read(&mut buf) {
            if n == 0 { break; }
            key_data.push(buf[0]);
            if key_data.len() > 32 { break; }
        }
        if key_data.len() < 32 {
            eprintln!("Error: expected 32 key bytes from stdin, found {}", key_data.len());
            std::process::exit(1);
        }
        if key_data.len() > 32 {
            eprintln!("Error: read more than 32 key bytes from stdin");
            std::process::exit(1);
        }
        key.copy_from_slice(&key_data);
    }

    if files.is_empty() { files.push("-".to_string()); }
    if raw && files.len() > 1 {
        eprintln!("Error: Only one filename can be provided when using --raw");
        std::process::exit(1);
    }

    let mut exit_code = 0;
    for path in &files {
        if keyed && path == "-" {
            eprintln!("b3sum: -: Cannot open `-` in keyed mode");
            exit_code = 1;
            continue;
        }
        let mut hasher = if keyed { Hasher::new_keyed(&key) }
                         else if let Some(ref ctx) = derive_key { Hasher::new_derive_key(ctx) }
                         else { Hasher::new() };
        let res = if path == "-" {
            hash_reader(io::stdin().lock(), &mut hasher)
        } else {
            match File::open(path) {
                Ok(f) => hash_reader(BufReader::new(f), &mut hasher),
                Err(e) => Err(e),
            }
        };
        if let Err(e) = res {
            eprintln!("b3sum: {}: {}", path, e);
            exit_code = 1;
            continue;
        }
        let mut out = vec![0u8; length];
        hasher.finalize_xof(seek, &mut out);
        if raw {
            let _ = io::stdout().write_all(&out);
        } else {
            let hex = hex_encode(&out);
            if tag { println!("BLAKE3 ({}) = {}", path, hex); }
            else if no_names { println!("{}", hex); }
            else { println!("{}  {}", hex, path); }
        }
    }
    std::process::exit(exit_code);
}

fn hash_reader<R: Read>(mut r: R, h: &mut Hasher) -> io::Result<()> {
    let mut buf = [0u8; 8192];
    loop {
        let n = r.read(&mut buf)?;
        if n == 0 { break; }
        h.update(&buf[..n]);
    }
    Ok(())
}

fn run_check(files: &[String], quiet: bool) {
    let mut failed = 0;
    let mut any_error = false;
    let mut files_to_check = files.to_vec();
    if files_to_check.is_empty() { files_to_check.push("-".to_string()); }

    for cf in &files_to_check {
        let reader: Box<dyn BufRead> = if cf == "-" { Box::new(BufReader::new(io::stdin().lock())) }
                                       else { match File::open(cf) {
                                           Ok(f) => Box::new(BufReader::new(f)),
                                           Err(e) => { eprintln!("b3sum: {}: {}", cf, e); any_error = true; continue; }
                                       }};
        for line in reader.lines() {
            let line = match line { Ok(l) => l, Err(_) => { any_error = true; break; }};
            if line.is_empty() { continue; }
            let (hash_str, path) = if line.starts_with("BLAKE3 (") {
                if let Some(idx) = line.rfind(" = ") {
                    let p = &line[8..idx];
                    if p.ends_with(')') { (&line[idx+3..], &p[..p.len()-1]) }
                    else { eprintln!("b3sum: Invalid check line format"); failed += 1; any_error = true; continue; }
                } else { eprintln!("b3sum: Invalid check line format"); failed += 1; any_error = true; continue; }
            } else if let Some(idx) = line.find("  ") {
                (&line[..idx], &line[idx+2..])
            } else { eprintln!("b3sum: Invalid check line format"); failed += 1; any_error = true; continue; };

            if hash_str.len() != 64 || !hash_str.chars().all(|c| c.is_ascii_hexdigit()) {
                eprintln!("b3sum: Invalid hash length");
                failed += 1; any_error = true; continue;
            }

            let mut h = Hasher::new();
            let res = match File::open(path) {
                Ok(f) => hash_reader(BufReader::new(f), &mut h),
                Err(e) => Err(e),
            };
            match res {
                Ok(_) => {
                    let mut out = [0u8; 32];
                    h.finalize_xof(0, &mut out);
                    if hex_encode(&out) == hash_str {
                        if !quiet { println!("{}: OK", path); }
                    } else { println!("{}: FAILED", path); failed += 1; any_error = true; }
                }
                Err(e) => { println!("{}: FAILED ({})", path, e); failed += 1; any_error = true; }
            }
        }
    }
    if failed > 0 {
        eprintln!("b3sum: WARNING: {} computed checksum{} did NOT match", failed, if failed > 1 { "s" } else { "" });
    }
    std::process::exit(if any_error || failed > 0 { 1 } else { 0 });
}

fn print_help() {
    println!("Usage: executable [OPTIONS] [FILE]...

Arguments:
  [FILE]...
          Files to hash, or checkfiles to check

          When no file is given, or when - is given, read standard input.

Options:
      --keyed
          Use the keyed mode, reading the 32-byte key from stdin

      --derive-key <CONTEXT>
          Use the key derivation mode, with the given context string

          Cannot be used with --keyed.

  -l, --length <LEN>
          The number of output bytes, before hex encoding

          [default: 32]

      --seek <SEEK>
          The starting output byte offset, before hex encoding

          [default: 0]

      --num-threads <NUM>
          The maximum number of threads to use

          By default, this is the number of logical cores. If this flag is omitted, or if its value
          is 0, RAYON_NUM_THREADS is also respected.

      --no-mmap
          Disable memory mapping

          Currently this also disables multithreading.

      --no-names
          Omit filenames in the output

      --raw
          Write raw output bytes to stdout, rather than hex

          --no-names is implied. In this case, only a single input is allowed.

      --tag
          Output BSD-style checksums: BLAKE3 ([FILE]) = [HASH]

  -c, --check
          Read BLAKE3 sums from the [FILE]s and check them

      --quiet
          Skip printing OK for each checked file

          Must be used with --check.

  -h, --help
          Print help (see more with '--help')

  -V, --version
          Print version");
}
